const item = $input.item.json;
const userId = item.user_id;
const rawEmail = item.email;
const products = item.matched_products || [];

// Read configuration from environment
const isTestMode = String($env.TEST_MODE || 'true').toLowerCase() === 'true';
const gmailUser = $env.GMAILUSER || 'atharva.test';
const fromEmail = $env.SES_FROM_EMAIL || 'notifications@example.com';

// TEST_MODE rewrite: Never send to sample CSV emails in test mode!
// Formats recipient as GMAILUSER+userid@gmail.com
const recipientEmail = isTestMode ? `${gmailUser}+${userId.replace(/[^a-zA-Z0-9]/g, '_')}@gmail.com` : rawEmail;

// Separate regular matches and near misses
const qualified = products.filter(p => !p.is_near_miss);
const nearMisses = products.filter(p => p.is_near_miss);

// Build HTML email
let html = `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px; border: 1px solid #e2e8f0; border-radius: 8px; background-color: #ffffff;">
  <div style="background-color: #1e293b; padding: 16px; border-radius: 6px; text-align: center;">
    <h2 style="color: #ffffff; margin: 0; font-size: 20px;">Personal Loan Pre-Qualification Results</h2>
  </div>
  <p style="color: #334155; font-size: 15px; margin-top: 20px;">Dear Applicant (<strong>${userId}</strong>),</p>
  <p style="color: #475569; font-size: 14px;">Based on your recent financial profile submission, we evaluated your eligibility across our network of lending partners.</p>
`;

if (qualified.length > 0) {
  html += `
  <h3 style="color: #0f172a; border-bottom: 2px solid #3b82f6; padding-bottom: 6px; margin-top: 24px;">Recommended Pre-Qualified Loan Products</h3>
  <table style="width: 100%; border-collapse: collapse; margin-top: 10px;">
    <thead>
      <tr style="background-color: #f1f5f9; text-align: left;">
        <th style="padding: 10px; border: 1px solid #cbd5e1; font-size: 13px;">Lender / Product</th>
        <th style="padding: 10px; border: 1px solid #cbd5e1; font-size: 13px;">Interest Rate</th>
        <th style="padding: 10px; border: 1px solid #cbd5e1; font-size: 13px;">Status</th>
      </tr>
    </thead>
    <tbody>
  `;
  for (const q of qualified) {
    html += `
      <tr>
        <td style="padding: 10px; border: 1px solid #cbd5e1; font-size: 13px;"><strong>${q.product_name}</strong><br><span style="color:#64748b; font-size:11px;">${q.source_site}</span></td>
        <td style="padding: 10px; border: 1px solid #cbd5e1; font-size: 13px; color: #16a34a; font-weight: bold;">${q.interest_rate}% p.a.</td>
        <td style="padding: 10px; border: 1px solid #cbd5e1; font-size: 13px;"><span style="background-color: #dcfce7; color: #15803d; padding: 3px 8px; border-radius: 12px; font-size: 11px; font-weight: 600;">Eligible</span></td>
      </tr>
    `;
  }
  html += `</tbody></table>`;
}

if (nearMisses.length > 0) {
  html += `
  <div style="margin-top: 24px; padding: 14px; background-color: #fffbeb; border: 1px solid #fef3c7; border-radius: 6px;">
    <h4 style="color: #92400e; margin: 0 0 8px 0; font-size: 14px;">Opportunities Within Reach (Near Misses)</h4>
  `;
  for (const nm of nearMisses) {
    html += `
      <p style="color: #78350f; font-size: 13px; margin: 4px 0;">
        • <strong>${nm.product_name}</strong> (${nm.interest_rate}% p.a.): ${nm.reason || 'Slightly below threshold'}.
      </p>
    `;
  }
  html += `</div>`;
}

html += `
  <p style="color: #94a3b8; font-size: 11px; margin-top: 30px; border-top: 1px solid #e2e8f0; padding-top: 12px;">
    Disclaimer: Pre-qualification does not guarantee credit approval. Final approval, terms, and conditions are subject to verification and formal lender policies.
  </p>
  <p style="color: #94a3b8; font-size: 10px;">
    Routing Note: Delivery directed to ${recipientEmail} (${isTestMode ? 'TEST MODE ACTIVE' : 'LIVE PRODUCTION'}).
  </p>
</div>
`;

// Build Plain Text fallback
let text = `Personal Loan Pre-Qualification Results

`;
text += `Dear Applicant (${userId}),

`;
text += `Eligible Products:
`;
for (const q of qualified) {
  text += `- ${q.product_name} (${q.source_site}): ${q.interest_rate}% p.a.
`;
}
if (nearMisses.length > 0) {
  text += `
Near Misses:
`;
  for (const nm of nearMisses) {
    text += `- ${nm.product_name}: ${nm.reason}
`;
  }
}
text += `
Disclaimer: Eligibility subject to lender verification.
`;

return {
  json: {
    batch_id: $node['Get Unnotified Matches'].json.batch_id,
    user_id: userId,
    recipient_email: recipientEmail,
    from_email: fromEmail,
    subject: `Your Personal Loan Eligibility Matches (Ref: ${userId})`,
    html_content: html,
    text_content: text
  }
};
